import React, { useState, useEffect } from "react";
import { useTranslation } from "gatsby-plugin-react-i18next";
import menuData from "../data/data.json";

const SubNavigation: React.FC = () => {
  const { t } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);
  const menuItems = menuData.submenu;
  const [moved, setMoved] = useState(false);
  const handleScroll = (id: string) => {
    const section = document.getElementById(id);
    if (section) {
      section.scrollIntoView({ behavior: "smooth" });
      setMoved(!moved);
      setIsOpen(!isOpen);
    }
  };

  const toggleMenu = () => {
    setMoved(!moved);
    setIsOpen(!isOpen);
  };

  return (
    <>
      <nav className="fixed bottom-0 sm:bottom-[unset] h-[3.75rem] w-full px-0 text-Tofu z-40">
        <div className="flex justify-between items-center w-full sm:px-[3.75rem] h-full bg-black/20 backdrop-blur-xl">
          {/* Desktop Menu */}
          <div className="hidden md:flex w-full justify-center">
            <ul className="flex space-x-6">
              {menuItems.map((item, index) => (
                <li key={index}>
                  <a
                    onClick={() => handleScroll(item)}
                    className="text-primary hover:text-secondary cursor-pointer"
                  >
                    {t(`submenu.${item}`)}
                  </a>
                </li>
              ))}
            </ul>
          </div>

          {/* Mobile Toggle Button */}
          <button
            onClick={toggleMenu}
            className="md:hidden flex justify-between px-4 w-full"
          >
            <span>{t("submenu.title")}</span>
            <img
              src="../down.svg"
              alt="Toggle menu"
              className={`w-6 h-6 transform transition-transform duration-300 ease-in-out ${
                isOpen ? "rotate-180" : "rotate-0"
              }`}
            />
          </button>
        </div>

        {/* Mobile Menu */}
        <div
          className={`transition-transform bottom-[60px] duration-700 ease-in-out transform z-[-1] absolute w-full ${
            moved ? "translate-y-[496px]" : "translate-y-0"
          }`}
        >
          <ul className="absolute bottom-full left-0 w-full bg-black/10 !backdrop-blur-md z-40 md:hidden shadow-lg">
            {menuItems.map((item, index) => (
              <li
                key={index}
                className={`p-4 ${
                  index < menuItems.length - 1 ? "border-b border-white/20" : ""
                }`}
              >
                <a
                  onClick={() => handleScroll(item)}
                  className="text-accent hover:text-secondary block"
                >
                  {t(`submenu.${item}`)}
                </a>
              </li>
            ))}
          </ul>
        </div>
      </nav>
    </>
  );
};

export default SubNavigation;
